-- -----------------------------------------------------
-- Table "user-main-app".User
-- -----------------------------------------------------
CREATE TABLE IF NOT EXISTS "User" (
  "ID" SERIAL PRIMARY KEY,
  "first_name" VARCHAR(45) NOT NULL,
  "last_name" VARCHAR(45),
  "email" TEXT NOT NULL,
  "linkedin" TEXT,
  "github" TEXT,
  "twitter" TEXT,
  "joined_timestamp" TIMESTAMP NOT NULL,
  "bio" TEXT,
  "phone_number" VARCHAR(45) NOT NULL,
  "display_name" VARCHAR(45),
  "setting_light_or_dark" VARCHAR(45),
  "setting_private_or_public" VARCHAR(45),
  "role_investor" BOOLEAN NOT NULL,
  "role_contributor" BOOLEAN NOT NULL,
  "role_founder" BOOLEAN NOT NULL,
  "legacy_score" INTEGER NOT NULL,
  "setting_verified" BOOLEAN NOT NULL,
  "verification_expiration" TIMESTAMP
);

-- -----------------------------------------------------
-- Table "user-main-app".Project
-- -----------------------------------------------------
CREATE TABLE IF NOT EXISTS "Project" (
  "ID" SERIAL PRIMARY KEY,
  "name" VARCHAR(255) NOT NULL,
  "logo" BYTEA,
  "description" TEXT,
  "post_date" TIMESTAMP NOT NULL,
  "business_plan" BYTEA,
  "video_link" TEXT NOT NULL,
  "score_metric" DECIMAL(10, 2) NOT NULL,
  "minimum_investment" DECIMAL(10, 2),
  "setting_open_or_closed_forinvestment" BOOLEAN NOT NULL,
  "status" VARCHAR(45) NOT NULL,
  "category" VARCHAR(45)
);

-- -----------------------------------------------------
-- Table "user-main-app".User_has_Projects_ownedby_Users
-- -----------------------------------------------------
CREATE TABLE IF NOT EXISTS "User_has_Projects_ownedby_Users" (
  "Project_ID" INTEGER NOT NULL,
  "User_ID" INTEGER NOT NULL,
  "owned_timestamp" TIMESTAMP,
  PRIMARY KEY ("Project_ID", "User_ID"),
  FOREIGN KEY ("Project_ID") REFERENCES "Project" ("ID") ON DELETE NO ACTION ON UPDATE NO ACTION,
  FOREIGN KEY ("User_ID") REFERENCES "User" ("ID") ON DELETE NO ACTION ON UPDATE NO ACTION
);

-- -----------------------------------------------------
-- Table "user-main-app".User_follows_Project_followedby_User
-- -----------------------------------------------------
CREATE TABLE IF NOT EXISTS "User_follows_Project_followedby_User" (
  "Project_ID" INTEGER NOT NULL,
