  "followed_timestamp" TIMESTAMP,
  PRIMARY KEY ("Project_ID", "User_ID"),
  FOREIGN KEY ("Project_ID") REFERENCES "Project" ("ID") ON DELETE NO ACTION ON UPDATE NO ACTION,
  FOREIGN KEY ("User_ID") REFERENCES "User" ("ID") ON DELETE NO ACTION ON UPDATE NO ACTION
);

-- -----------------------------------------------------
-- Table "user-main-app".Users_follow_Users_followedby_Users
-- -----------------------------------------------------
CREATE TABLE IF NOT EXISTS "Users_follow_Users_followedby_Users" (
  "User_ID_follower" INTEGER NOT NULL,
  "User_ID_following" INTEGER NOT NULL,
  PRIMARY KEY ("User_ID_follower", "User_ID_following"),
  FOREIGN KEY ("User_ID_follower") REFERENCES "User" ("ID") ON DELETE NO ACTION ON UPDATE NO ACTION,
  FOREIGN KEY ("User_ID_following") REFERENCES "User" ("ID") ON DELETE NO ACTION ON UPDATE NO ACTION
);

-- -----------------------------------------------------
-- Table "user-main-app".Updates
-- -----------------------------------------------------
CREATE TABLE IF NOT EXISTS "Updates" (
  "ID" SERIAL NOT NULL,
  "User_ID" INTEGER NOT NULL,
  "Project_ID" INTEGER NOT NULL,
  "title" TEXT NOT NULL,
