  "posted_timestamp" TIMESTAMP NOT NULL,
  PRIMARY KEY ("ID", "User_ID", "Project_ID"),
  FOREIGN KEY ("User_ID", "Project_ID") REFERENCES "User_has_Projects_ownedby_Users" ("User_ID", "Project_ID") ON DELETE NO ACTION ON UPDATE NO ACTION
);

-- -----------------------------------------------------
